import { test, expect } from '@playwright/test';

test.describe('Filtered Search URL Sharing', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search');
  });

  test('should successfully share a filtered search URL with another user', async ({ page }) => {
    // Set up initial search filter
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('Playwright');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Verify search results are displayed
    const resultList = page.getByRole('list');
    await expect(resultList).toBeVisible();

    // Verify search URL contains the filter term
    const searchUrl = page.url();
    expect(searchUrl).toContain('q=Playwright');

    // Share the search URL using a share button
    const shareButton = page.getByRole('button', { name: /share/i });
    await shareButton.click();

    // Verify share modal appears
    const shareModal = page.getByRole('dialog');
    await expect(shareModal).toBeVisible();

    // Verify share button is visible
    const shareButton = page.getByRole('button', { name: /share/i });
    await expect(shareButton).toBeVisible();

    // Click share button
    await shareButton.click();

    // Verify share confirmation message appears
    const confirmationMessage = page.getByText(/shared successfully/i);
    await expect(confirmationMessage).toBeVisible();

    // Verify URL is copied to clipboard
    const clipboard = page.getByRole('status');
    await expect(clipboard).toContainText('URL copied to clipboard');

    // Verify modal closes
    await expect(shareModal).not.toBeVisible();

    // Verify search results are still visible
    await expect(resultList).toBeVisible();
  });

  test('should handle sharing a filtered search URL with invalid characters', async ({ page }) => {
    // Set up initial search filter with invalid characters
    const searchInput = page.getByLabel('Search');
    await searchInput.fill('Playwright*');

    const searchButton = page.getByRole('button', { name: /search/i });
    await searchButton.click();

    // Verify search results are displayed
    const resultList = page.getByRole('list');
    await expect(resultList).toBeVisible();

    // Share the search URL using a share button
    const shareButton = page.getByRole('button', { name: /share/i });
    await shareButton.click();

    // Verify share modal appears
    const shareModal = page.getByRole('dialog');
    await expect(shareModal).toBeVisible();

    // Verify share button is visible
    const shareButton = page.getByRole('button', { name: /share/i });
    await expect(shareButton).toBeVisible();

    // Click share button
    await shareButton.click();

    // Verify share confirmation message appears
    const confirmationMessage = page.getByText(/shared successfully/i);
    await expect(confirmationMessage).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText(/invalid characters/i);
    await expect(errorMessage).toBeVisible();

    // Verify share modal closes
    await expect(shareModal).not.toBeVisible();

    // Verify search results are still visible
    await expect(resultList).toBeVisible();
  });
});
